(r, big) => {
    const n = big ? 5000 : r.int(1, 7);
    const perm = r.shuffle(Array.from({ length: n }, (_, i) => i + 1));
    const seen = new Set(), edges = [];
    const add = (a, b) => { const k = a * 10000 + b; if (a !== b && !seen.has(k)) { seen.add(k); edges.push([a, b]); } };
    if (big) {
      for (let i = 0; i + 1 < n; i++) add(perm[i], perm[i + 1]);
      add(perm[r.int(0, 10)], perm[r.int(4990, 4999)]);
      return [n, edges];
    }
    const dag = r.bool(0.7), m = r.int(0, Math.min(8, n * (n - 1)));
    for (let t = 0; t < m * 3 && edges.length < m; t++) {
      let i = r.int(0, n - 1), j = r.int(0, n - 1);
      if (dag && i > j) [i, j] = [j, i];
      add(perm[i], perm[j]);
    }
    return [n, r.shuffle(edges)];
  }

