function fewestTerms(n: number, prereqs: number[][]): number {
  const doneIn = new Array(n + 1).fill(0); // term the course was finished in, 0 = not yet
  let taken = 0, term = 0;
  while (taken < n) {
    term++;
    const blocked = new Array(n + 1).fill(false);
    for (const [a, b] of prereqs) if (doneIn[a] === 0) blocked[b] = true;
    let progress = false;
    for (let c = 1; c <= n; c++) {
      if (doneIn[c] === 0 && !blocked[c]) { doneIn[c] = term; taken++; progress = true; }
    }
    if (!progress) return -1;
  }
  return term;
}

