    def fewestTerms(self, n: int, prereqs: List[List[int]]) -> int:
        done = [False] * (n + 1)
        taken = term = 0
        while taken < n:
            term += 1
            blocked = [False] * (n + 1)
            for a, b in prereqs:
                if not done[a]:
                    blocked[b] = True
            batch = [c for c in range(1, n + 1) if not done[c] and not blocked[c]]
            if not batch:
                return -1
            for c in batch:
                done[c] = True
            taken += len(batch)
        return term

