function fewestTerms(n: number, prereqs: number[][]): number {
  const next: number[][] = Array.from({ length: n + 1 }, () => []);
  const indeg = new Array(n + 1).fill(0);
  for (const [a, b] of prereqs) { next[a].push(b); indeg[b]++; }
  let level: number[] = [];
  for (let c = 1; c <= n; c++) if (indeg[c] === 0) level.push(c);
  let terms = 0, taken = 0;
  while (level.length > 0) {
    terms++;
    taken += level.length;
    const upcoming: number[] = [];
    for (const c of level) {
      for (const d of next[c]) if (--indeg[d] === 0) upcoming.push(d);
    }
    level = upcoming;
  }
  return taken === n ? terms : -1;
}

