class Solution:
    def fewestTerms(self, n: int, prereqs: List[List[int]]) -> int:
        nxt = [[] for _ in range(n + 1)]
        indeg = [0] * (n + 1)
        for a, b in prereqs:
            nxt[a].append(b)
            indeg[b] += 1
        level = [c for c in range(1, n + 1) if indeg[c] == 0]
        terms = taken = 0
        while level:
            terms += 1
            taken += len(level)
            upcoming = []
            for c in level:
                for d in nxt[c]:
                    indeg[d] -= 1
                    if indeg[d] == 0:
                        upcoming.append(d)
            level = upcoming
        return terms if taken == n else -1

